skins.css:
/* RAGNAROK — a 2002 MMO client.
   Every surface is a plate with thickness: lit along the top and left, shaded
   along the bottom and right. Nothing floats, nothing fades, and a button
   physically goes IN when you press it.
   No layout is touched. Only the drawing of each box changes. */

body { letter-spacing: var(--track-body) }

/* ---- the title bar ---- */
header {
  background: linear-gradient(180deg, rgba(255,255,255,.24), rgba(0,0,0,.22)), var(--accent);
  color: var(--accent-fg);
  border-bottom: 2px solid rgba(0,0,0,.5);
  box-shadow: inset 1px 1px 0 rgba(255,255,255,.34);
}
header .logo {
  font-family: var(--font-display);
  font-size: var(--f-2);
  color: var(--accent-fg);
  letter-spacing: var(--track-cap);
  text-shadow: 1px 1px 0 rgba(0,0,0,.6);
}
header .logo b { color: var(--accent-fg); opacity: .7 }

/* ---- plates: anything that holds content ---- */
.card, .mb-sheet, .mb-toast, .mb-menu {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-2);
}

/* A window gets a proper title strip, not a heading floating on the plate. */
.mb-sheet-head {
  background: linear-gradient(180deg, rgba(255,255,255,.24), rgba(0,0,0,.22)), var(--accent);
  color: var(--accent-fg);
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  text-shadow: 1px 1px 0 rgba(0,0,0,.6);
  box-shadow: inset 1px 1px 0 rgba(255,255,255,.34);
}
.mb-sheet-head .mb-grab { background: rgba(255,255,255,.5) }

/* A section heading is a stamped label with a rule under it. */
h2 {
  font-family: var(--font-display);
  color: var(--text-1);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
  text-shadow: 1px 1px 0 rgba(255,255,255,.6);
}

/* ---- wells: rows, inputs, tracks. Pressed into the plate. ---- */
.item, .mb-input, .mb-sel, .mb-range, .mb-sw {
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--bevel-in);
}

/* ---- buttons: raised, and they go in under the finger ---- */
button.mb-btn, .mb-act, button.chk, #fab, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: var(--surface-3);
  color: var(--text-1);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-1);
  transition: none;
}
button.mb-btn:active, .mb-act:active, button.chk:active,
#fab:active, .mb-chip:active, .mb-x:active, .mb-opt:active {
  box-shadow: var(--bevel-in);
  transform: translate(1px, 1px);
}

/* The one loud action keeps the accent, but as a plate rather than a pill. */
#fab {
  background: linear-gradient(180deg, rgba(255,255,255,.24), rgba(0,0,0,.2)), var(--accent);
  color: var(--accent-fg);
  border-radius: 0;
  font-family: var(--font-display);
  font-size: var(--f-5);
  text-shadow: 1px 1px 0 rgba(0,0,0,.5);
}

/* A ticked box is a lit gem set into the plate, not a filled circle. */
button.chk { border-radius: 0 }
button.chk.on {
  background: linear-gradient(180deg, rgba(255,255,255,.3), rgba(0,0,0,.2)), var(--accent);
  color: var(--accent-fg);
  box-shadow: var(--e-1);
}

/* Selection is a hard inverted bar, the way a list worked before hover did. */
.mb-opt:hover, .mb-chip.on {
  background: var(--accent);
  color: var(--accent-fg);
}

/* SYSTEM - a levelling-up status window. Light comes OFF the surfaces instead
   of falling onto them, every frame is a hairline, and the corners are cut
   with brackets rather than rounded. */

body { letter-spacing: var(--track-body) }

header {
  background: transparent;
  border-bottom: var(--border-width) solid var(--border);
  box-shadow: 0 1px 0 rgba(127,227,255,.10);
}
header .logo {
  font-family: var(--font-display);
  color: var(--text-1);
  text-shadow: 0 0 14px var(--accent);
}
header .logo b { color: var(--accent); text-shadow: 0 0 18px var(--accent) }

/* A panel is a pane of lit glass, not a solid card. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: linear-gradient(180deg, rgba(127,227,255,.05), rgba(127,227,255,.012));
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-1);
}
/* Bracket corners. Two pseudo-elements on opposite corners, no new markup. */
.card::before, .card::after {
  content: ''; position: absolute; width: 15px; height: 15px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0 }
.card::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0 }

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  text-shadow: 0 0 12px var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* A row is a ruled line in a readout, not a filled pill. */
.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 2px; border-color: var(--border-strong) }
.chk.on { box-shadow: var(--e-2); border-color: var(--accent) }

/* The numbers are the whole point of a status window, so they glow. */
.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { color: var(--text-1); text-shadow: 0 0 16px var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: var(--accent); color: var(--accent-fg) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); box-shadow: var(--e-2) }

.mb-input, .mb-sel { background: rgba(127,227,255,.05); border-color: var(--border) }
#fab { box-shadow: var(--e-3); border: var(--border-width) solid var(--accent) }

/* MONARCH - black and gold. Nothing floats and almost nothing is filled: the
   whole design is hairlines, capitals and empty space. */

body { letter-spacing: var(--track-body) }

header { background: var(--bg); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-2) }

/* A card is a ruled box with a second line just inside it. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--bg);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 3px var(--bg), inset 0 0 0 4px var(--border);
  padding: var(--s-5);
}

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-chip:active,
.mb-btn.go { background: var(--accent); color: var(--accent-fg) }

.mb-input, .mb-sel { background: transparent; border-color: var(--border);
  border-radius: 0; color: var(--text-1) }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  font-family: var(--font-display) }

/* ORNATE - a grey plate in a gold frame, with a diamond on every rule. The
   flourishes are pseudo-elements on things that already exist, so no app grows
   a single new element. */

body { letter-spacing: var(--track-body) }

header { background: var(--surface-1); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-1) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: var(--surface-1);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 4px var(--surface-1), inset 0 0 0 5px var(--border);
  padding: var(--s-5);
}
/* Gold corner flourishes on opposite corners, drawn rather than fetched. */
.card::before, .card::after {
  content: ''; position: absolute; width: 16px; height: 16px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: 5px; left: 5px; border-right: 0; border-bottom: 0 }
.card::after { bottom: 5px; right: 5px; border-left: 0; border-top: 0 }

/* A heading is centred and ruled, and the rule is broken by a diamond. */
h2 {
  position: relative;
  font-family: var(--font-display);
  text-align: center;
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-3);
}
h2::after {
  content: '\25C6';
  position: absolute; left: 50%; bottom: -7px; transform: translateX(-50%);
  background: var(--surface-1); padding: 0 6px;
  color: var(--accent); font-size: 10px; line-height: 1;
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-btn.go {
  background: var(--accent); color: var(--accent-fg);
}
.mb-input, .mb-sel { background: var(--surface-2); border-color: var(--border); border-radius: 0 }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  border: 2px solid var(--border-strong); font-family: var(--font-display) }

/* DECK - a presentation slide. A deep blue gradient, hairline rules, generous
   capitals, and rows that band the way a table on a slide does. */

body { letter-spacing: var(--track-body) }

header { background: transparent; border-bottom: var(--border-width) solid var(--border) }
header .logo { font-family: var(--font-display); color: var(--text-1) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: rgba(255,255,255,.055);
  border: var(--border-width) solid var(--border);
}

h2 {
  font-family: var(--font-display);
  color: var(--text-1);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* Banded rows. It has to work whether or not the row is wrapped for the swipe
   gesture, so both shapes are named. */
.item, .list > *:nth-child(odd) .item { background: rgba(255,255,255,.05) }
.list > *:nth-child(even) .item, .item:nth-child(even) { background: rgba(255,255,255,.10) }
.item.on .nm { color: var(--text-muted) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.stat { background: rgba(255,255,255,.07); border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--text-1) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--text-1);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: rgba(255,255,255,.16) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.mb-input, .mb-sel { background: rgba(255,255,255,.09); border-color: var(--border);
  color: var(--text-1) }
#fab { background: var(--accent); color: var(--accent-fg) }
